"""Policy-as-code evaluator for data retention rules.

Loads rules from policies/retention.yaml. For a given record, the most
specific matching rule wins (more matched applies_to keys beats fewer).
A specificity tie is a spec error and raises PolicyError.
"""

from __future__ import annotations

import os
from pathlib import Path

import yaml

POLICY_PATH = Path(os.environ.get("RETENTION_POLICY", "policies/retention.yaml"))


class PolicyError(Exception):
    """Raised for malformed or ambiguous policy specifications."""


class _Policy:
    def __init__(self, path: Path = POLICY_PATH) -> None:
        with open(path, "r", encoding="utf-8") as f:
            doc = yaml.safe_load(f)

        if not isinstance(doc, dict):
            raise PolicyError("policy document must be a mapping")

        self.default = doc.get("default")
        if not isinstance(self.default, str) or not self.default:
            raise PolicyError("policy must define a non-empty 'default' action")

        self.rules = []
        raw_rules = doc.get("rules")
        if not isinstance(raw_rules, list):
            raise PolicyError("policy must define a 'rules' list")

        for entry in raw_rules:
            if not isinstance(entry, dict):
                raise PolicyError("each rule must be a mapping")
            rule_id = entry.get("id")
            applies_to = entry.get("applies_to", {})
            max_age = entry.get("max_age_days")
            if not isinstance(rule_id, str) or not rule_id:
                raise PolicyError("rule missing 'id'")
            if not isinstance(applies_to, dict) or not all(
                isinstance(k, str) and isinstance(v, (str, int, float, bool))
                for k, v in applies_to.items()
            ):
                raise PolicyError(f"rule {rule_id}: invalid 'applies_to'")
            if not isinstance(max_age, int) or isinstance(max_age, bool) or max_age < 0:
                raise PolicyError(f"rule {rule_id}: 'max_age_days' must be a non-negative integer")
            self.rules.append({"id": rule_id, "applies_to": dict(applies_to), "max_age_days": max_age})

    def evaluate(self, record: dict) -> tuple[str, str | None]:
        """Return (action, reason). action is KEEP or PURGE.

        reason is the winning rule id, or the policy default name when no
        rule matched.
        """
        category = record.get("category")
        age_days = record.get("age_days")
        if age_days is None:
            raise PolicyError("record missing 'age_days'")

        matches = [
            r
            for r in self.rules
            if all(record.get(k) == v for k, v in r["applies_to"].items())
        ]

        if not matches:
            return ("PURGE", self.default)

        best = max(len(r["applies_to"]) for r in matches)
        winners = [r for r in matches if len(r["applies_to"]) == best]
        if len(winners) > 1:
            ids = ", ".join(sorted(w["id"] for w in winners))
            raise PolicyError(f"ambiguous policy: tie between rules [{ids}]")

        winner = winners[0]
        action = "KEEP" if age_days <= winner["max_age_days"] else "PURGE"
        return (action, winner["id"])


_policy = None


def get_policy() -> _Policy:
    global _policy
    if _policy is None:
        _policy = _Policy(POLICY_PATH)
    return _policy


def reset_policy() -> None:
    """Force reload on next evaluation (useful for tests)."""
    global _policy
    _policy = None


def evaluate(record: dict) -> tuple[str, str | None]:
    return get_policy().evaluate(record)


if __name__ == "__main__":
    import json
    import sys

    record = json.loads(sys.argv[1])
    action, reason = evaluate(record)
    print(json.dumps({"action": action, "reason": reason}))

